<script setup>
import { ref, computed, onMounted, onUnmounted, watch } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { useAppStore } from '../stores/app'
import api, { trainingSocket } from '../api/client'
import TopologyGraph from '../components/TopologyGraph.vue'
import NodeResourcePanel from '../components/NodeResourcePanel.vue'
import MetricCharts from '../components/MetricCharts.vue'
const app = useAppStore(), snapshot = ref(null), selected = ref(null), configs = ref([]), savedId = ref(null), metrics = ref({training:[],evaluation:[]}), run = ref(null), tab = ref('environment'); let socket
const groups = [ ['规模与任务流', [['n_terminals','端侧数量'],['n_edges','边缘节点'],['episode_slots','时隙数'],['arrival_rate','到达率'],['burst_prob','突发概率'],['burst_multiplier','突发倍数'],['hotspot_fraction','热点占比'],['hotspot_share','热点流量占比'],['deadline_slack_min','时限松弛下限'],['deadline_slack_max','时限松弛上限']]], ['动态拓扑与链路', [['topology_period_slots','拓扑周期'],['undirected_edge_links','边缘链路数'],['max_hops','最大跳数'],['k_routes_per_destination','每目标候选路径'],['link_flap_prob','链路瞬断概率'],['congestion_ar_coef','拥塞自回归系数'],['congestion_step_noise','拥塞步进噪声'],['link_spike_prob','拥塞尖峰概率'],['link_rate_fluctuation','链路速率波动'],['congestion_min','拥塞下限'],['congestion_max','拥塞上限'],['link_rate_min_mbps','链路速率下限 Mbps'],['link_rate_max_mbps','链路速率上限 Mbps']]] ]
const trainFields = [['gat_hidden_dim','GAT 隐层'],['actor_hidden_dim','Actor 隐层'],['critic_hidden_dim','Critic 隐层'],['actor_learning_rate','Actor 学习率'],['critic_learning_rate','Critic 学习率'],['gamma','折扣因子 γ'],['gae_lambda','GAE λ'],['ppo_clip','PPO Clip'],['ppo_epochs','PPO 更新轮次'],['ppo_batch_size','Batch size'],['ent_coef','熵系数'],['eval_interval','评估间隔']]
const progress = computed(()=>run.value?.episodes ? Math.min(100,Math.round(100*(run.value.current_episode || 0)/run.value.episodes)) : 0)
const latest = computed(()=>metrics.value.training.at(-1) || {})
watch(() => app.env?.config.n_edges, count => { if (!count || !app.env?.config.edge_speed_matrix) return; const c=app.env.config; while (c.edge_speed_matrix.length < count) { c.edge_speed_matrix.push([...c.edge_speed_matrix[c.edge_speed_matrix.length % 4]]); c.service_deployment.push([...c.service_deployment[c.service_deployment.length % 4]]) } c.edge_speed_matrix.length=count; c.service_deployment.length=count })
function preset(name){ app.env = {preset_name:name,config:structuredClone(app.presets[name])}; savedId.value=null }
async function preview(){ snapshot.value = await api.post('/env/preview',app.env); selected.value = snapshot.value.nodes[0] }
async function save(){ const {value} = await ElMessageBox.prompt('为当前环境配置命名','保存到 MySQL',{inputValue:'我的环境配置'}); await api.post('/env/configs',{...app.env,name:value}); ElMessage.success('环境配置已保存'); configs.value = await api.get('/env/configs') }
function loadSaved(id){ const c = configs.value.find(c=>c.id===id); app.env = {preset_name:c.preset_name,config:structuredClone(c.config_json)} }
function connect(id){ if(socket) socket.close(); socket = trainingSocket(id); socket.onmessage = event => { const e=JSON.parse(event.data); if(e.type==='metric') metrics.value.training.push(e.metrics); if(e.type==='evaluation') metrics.value.evaluation.push(e.metrics); if(e.metrics?.episode && run.value) run.value.current_episode=e.metrics.episode; if(e.type==='status' && run.value) run.value.status=e.status; if(e.type==='terminal') { if(run.value) run.value.status=e.status; app.checkHealth() } } }
async function monitor(id){ run.value=await api.get(`/training/runs/${id}`); metrics.value=await api.get(`/training/runs/${id}/metrics`); if(['running','queued'].includes(run.value.status)) { metrics.value={training:[],evaluation:[]}; connect(id) } }
async function start(){ const config={...app.env.config}; trainFields.forEach(([key])=>{ if(app.train[key] != null) config[key]=app.train[key] }); const result=await api.post('/training/runs',{...app.env,...app.train,config}); app.activeRun=result.run_id; run.value=result; metrics.value={training:[],evaluation:[]}; connect(result.run_id); tab.value='monitor'; app.checkHealth() }
async function stop(){ await api.post(`/training/runs/${app.activeRun}/stop`); ElMessage.success('已请求安全中断，正在保存') }
onMounted(async()=>{ if(!Object.keys(app.presets).length) await app.loadPresets(); await app.checkHealth(); if(app.health?.db_connected) configs.value=await api.get('/env/configs'); if(app.activeRun) await monitor(app.activeRun) }); onUnmounted(()=>socket?.close())
</script>
<template><div class="page"><div class="page-head"><div><div class="eyebrow">TRAINING WORKBENCH</div><h1>模型训练工作台</h1><p>搭建仿真环境，配置策略网络并监控训练过程。</p></div><div class="page-code">调度研究 / 01</div></div><el-tabs v-model="tab" class="work-tabs"><el-tab-pane label="01  环境搭建" name="environment"><template v-if="app.env"><div class="toolbar panel"><div><span class="field-label">场景预设</span><el-select :model-value="app.env.preset_name" style="width:180px" @change="preset"><el-option v-for="p in ['default','high_congestion','small_smoke']" :key="p" :value="p" :label="p"/></el-select></div><div><span class="field-label">已保存配置</span><el-select v-model="savedId" placeholder="从 MySQL 加载" clearable style="width:180px" @change="id => id && loadSaved(id)"><el-option v-for="c in configs" :key="c.id" :label="c.name" :value="c.id"/></el-select></div><div class="toolbar-actions"><el-button @click="app.resetEnv()">重置草稿</el-button><el-button @click="save">保存配置到 MySQL</el-button><el-button type="primary" @click="preview">预览仿真拓扑</el-button></div></div><div class="work-grid"><div class="stack"><section v-for="group in groups" :key="group[0]" class="panel"><div class="panel-heading"><h3>{{ group[0] }}</h3><span class="muted">参数自动保存</span></div><div class="form-grid"><label v-for="field in group[1]" :key="field[0]"><span>{{ field[1] }} <small>{{ field[0] }}</small></span><el-input-number v-model="app.env.config[field[0]]" :controls="false" :step="0.01" /></label></div></section><section class="panel"><div class="panel-heading"><div><h3>异构算力与服务部署</h3><p class="muted">逐节点编辑算力及任务服务</p></div><span class="chip">GFLOP/s</span></div><div class="matrix-wrap"><table class="matrix"><thead><tr><th>节点</th><th v-for="x in ['CPU','NPU','FPGA','T0','T1','T2','T3','T4']" :key="x">{{ x }}</th></tr></thead><tbody><tr v-for="(row,i) in app.env.config.edge_speed_matrix" :key="i"><td>E{{ i }}</td><td v-for="(_,j) in row" :key="j"><input type="number" v-model.number="row[j]"></td><td v-for="(_,j) in app.env.config.service_deployment[i]" :key="j"><input type="checkbox" :checked="!!app.env.config.service_deployment[i][j]" @change="app.env.config.service_deployment[i][j]=$event.target.checked ? 1 : 0"></td></tr></tbody></table></div><p class="muted">T0 图像识别 · T1 目标检测 · T2 视频分析 · T3 语音处理 · T4 信号计算</p></section></div><div class="stack"><section class="panel"><div class="panel-heading"><div><div class="eyebrow">TOPOLOGY PREVIEW</div><h3>环境拓扑预览</h3></div><span class="chip">实时快照</span></div><TopologyGraph :snapshot="snapshot" @select-node="selected=$event" /></section><section class="panel"><NodeResourcePanel :node="selected" :nodes="snapshot?.nodes || []" @select-node="selected=$event"/></section></div></div></template></el-tab-pane><el-tab-pane label="02  算法参数" name="algorithm"><div class="panel"><div class="panel-heading"><div><div class="eyebrow">POLICY CONFIGURATION</div><h3>算法与网络参数</h3></div><el-button @click="app.resetTrain()">重置草稿</el-button></div><div class="form-grid wide"><label><span>模型</span><el-select v-model="app.train.model_type"><el-option label="GAT-PPO" value="gat"/><el-option label="单纯 PPO" value="flat"/><el-option label="打乱图消融" value="shuffled_gat"/></el-select></label><label v-for="field in trainFields" :key="field[0]"><span>{{ field[1] }} <small>{{ field[0] }}</small></span><el-input-number v-model="app.train[field[0]]" :placeholder="String(app.env?.config[field[0]] ?? '')" :controls="false" /></label><label v-for="field in [['episodes','训练回合'],['seed','随机种子'],['threads','线程数']]" :key="field[0]"><span>{{ field[1] }}</span><el-input-number v-model="app.train[field[0]]" :controls="false"/></label><label><span>设备</span><el-select v-model="app.train.device"><el-option v-for="v in ['cpu','cuda','auto']" :key="v" :value="v"/></el-select></label><label class="span-two"><span>续训 Checkpoint</span><el-select v-model="app.train.resume_path" clearable filterable placeholder="不续训"><el-option v-for="c in app.checkpoints" :key="c.path" :label="c.run_dir + ' / ' + c.name" :value="c.path"/></el-select></label></div><div class="form-footer"><el-button type="primary" @click="tab='monitor'">继续到训练监控 →</el-button></div></div></el-tab-pane><el-tab-pane label="03  训练监控" name="monitor"><div class="panel monitor-head"><div><div class="eyebrow">LIVE TRAINING</div><h3>{{ run?.run_name || '准备开始训练' }}</h3><p class="muted">{{ run ? `状态：${run.status} · 回合 ${run.current_episode || 0} / ${run.episodes}` : '启动后实时展示训练指标' }}</p></div><div><el-button @click="stop" :disabled="!app.activeRun || !['running','queued'].includes(run?.status)">安全中断并保存</el-button><el-button type="primary" @click="start" :disabled="['running','queued'].includes(run?.status)">启动训练</el-button></div></div><el-progress :percentage="progress" :stroke-width="5" /><div class="kpi-grid"><div v-for="k in [['任务完成率','task_success_rate'],['平均时延','avg_delay_s'],['平均能耗','avg_energy_j'],['负载方差','mean_load_variance']]" :key="k[1]" class="kpi"><span>{{ k[0] }}</span><strong>{{ latest[k[1]] == null ? '—' : Number(latest[k[1]]).toFixed(3) }}</strong></div></div><MetricCharts :metrics="metrics"/></el-tab-pane></el-tabs></div></template>
